using BARANG.Core.Domain.Common;
namespace BARANG.Core.Domain.Background;
public enum OutboxStatus{Pending,Processing,Processed,DeadLetter}public enum NotificationChannel{InApp,Sms,Email,Push}public enum NotificationStatus{Pending,Sent,Failed}public enum DeadLetterStatus{Open,RetryRequested,Resolved}
public static class BackgroundErrors{public static Error Invalid=>Error.Validation("background.invalid_data");public static Error NotFound=>Error.NotFound("background.not_found");public static Error Concurrency=>Error.Concurrency("background.concurrency_conflict");public static Error InvalidTransition=>Error.BusinessRule("background.invalid_transition");}
public sealed class OutboxMessage
{private OutboxMessage(){}public Guid Id{get;private set;}public Guid?CompanyId{get;private set;}public string EventType{get;private set;}="";public string Payload{get;private set;}="{}";public string CorrelationId{get;private set;}="";public DateTimeOffset OccurredAtUtc{get;private set;}public DateTimeOffset?ProcessedAtUtc{get;private set;}public int Attempts{get;private set;}public OutboxStatus Status{get;private set;}public DateTimeOffset NextAttemptAtUtc{get;private set;}public string?LastErrorCode{get;private set;}public long Version{get;private set;}public static Result<OutboxMessage>Create(Guid?company,string type,string payload,string correlation,DateTimeOffset now){string t=type.Trim(),c=correlation.Trim();if(t.Length is<3 or>100||payload.Length>8000||c.Length is<1 or>100)return Result.Failure<OutboxMessage>(BackgroundErrors.Invalid);return Result.Success(new OutboxMessage(){Id=Guid.NewGuid(),CompanyId=company,EventType=t,Payload=payload,CorrelationId=c,OccurredAtUtc=now,Status=OutboxStatus.Pending,NextAttemptAtUtc=now,Version=1});}public void Start(DateTimeOffset now){if(Status is OutboxStatus.Pending){Status=OutboxStatus.Processing;Attempts++;Version++;}}public void Succeed(DateTimeOffset now){Status=OutboxStatus.Processed;ProcessedAtUtc=now;LastErrorCode=null;Version++;}public void Retry(string code,DateTimeOffset next){Status=OutboxStatus.Pending;LastErrorCode=Safe(code,100);NextAttemptAtUtc=next;Version++;}public void Dead(string code){Status=OutboxStatus.DeadLetter;LastErrorCode=Safe(code,100);Version++;}public void ManualRetry(DateTimeOffset now){if(Status!=OutboxStatus.DeadLetter)return;Status=OutboxStatus.Pending;NextAttemptAtUtc=now;LastErrorCode=null;Version++;}private static string Safe(string x,int n)=>x[..Math.Min(x.Length,n)];}
public sealed class Notification
{private Notification(){}public Guid Id{get;private set;}public Guid CompanyId{get;private set;}public Guid RecipientUserId{get;private set;}public NotificationChannel Channel{get;private set;}public string TemplateCode{get;private set;}="";public string Payload{get;private set;}="{}";public NotificationStatus Status{get;private set;}public int AttemptCount{get;private set;}public DateTimeOffset ScheduledAtUtc{get;private set;}public DateTimeOffset CreatedAtUtc{get;private set;}public DateTimeOffset?SentAtUtc{get;private set;}public DateTimeOffset?FailedAtUtc{get;private set;}public string?FailureCode{get;private set;}public DateTimeOffset?ReadAtUtc{get;private set;}public long Version{get;private set;}public static Result<Notification>Create(Guid company,Guid recipient,NotificationChannel channel,string template,string payload,DateTimeOffset now){string t=template.Trim();if(company==Guid.Empty||recipient==Guid.Empty||t.Length is<3 or>100||payload.Length>4000)return Result.Failure<Notification>(BackgroundErrors.Invalid);return Result.Success(new Notification(){Id=Guid.NewGuid(),CompanyId=company,RecipientUserId=recipient,Channel=channel,TemplateCode=t,Payload=payload,Status=NotificationStatus.Pending,ScheduledAtUtc=now,CreatedAtUtc=now,Version=1});}public void Sent(DateTimeOffset now){Status=NotificationStatus.Sent;AttemptCount++;SentAtUtc=now;FailureCode=null;Version++;}public void Fail(string code,DateTimeOffset now){Status=NotificationStatus.Failed;AttemptCount++;FailedAtUtc=now;FailureCode=code[..Math.Min(code.Length,100)];Version++;}public Result Read(Guid actor,long expected,DateTimeOffset now){if(actor!=RecipientUserId)return Result.Failure(BackgroundErrors.NotFound);if(ReadAtUtc is not null)return Result.Success();if(expected!=Version)return Result.Failure(BackgroundErrors.Concurrency);ReadAtUtc=now;Version++;return Result.Success();}}
public sealed class DeadLetterItem
{private DeadLetterItem(){}public Guid Id{get;private set;}public Guid CompanyId{get;private set;}public Guid OutboxMessageId{get;private set;}public string ErrorCode{get;private set;}="";public DeadLetterStatus Status{get;private set;}public DateTimeOffset CreatedAtUtc{get;private set;}public DateTimeOffset?ReviewedAtUtc{get;private set;}public Guid?ReviewedByUserId{get;private set;}public long Version{get;private set;}public static DeadLetterItem Create(Guid company,Guid message,string code,DateTimeOffset now)=>new(){Id=Guid.NewGuid(),CompanyId=company,OutboxMessageId=message,ErrorCode=code[..Math.Min(code.Length,100)],Status=DeadLetterStatus.Open,CreatedAtUtc=now,Version=1};public Result RequestRetry(Guid actor,long expected,DateTimeOffset now){if(expected!=Version)return Result.Failure(BackgroundErrors.Concurrency);if(Status!=DeadLetterStatus.Open)return Result.Failure(BackgroundErrors.InvalidTransition);Status=DeadLetterStatus.RetryRequested;ReviewedAtUtc=now;ReviewedByUserId=actor;Version++;return Result.Success();}}
